#include "StdAfx.h"#include <StateSer.h>#include <CommProc.h>#include <sr.h>KStateSer::KStateSer(void){}KStateSer::~KStateSer(void){}void KStateSer::Write( LPCSTR pStr ){  size_t l = strlen( pStr )+1;  Write( l );  WriteImpl( pStr, l );}void KStateSer::Write( DWORD objSize, const void *pObj ){  WriteImpl( pObj, objSize );}void KStateSer::WriteImpl( const void *pObj, DWORD objSize ){  pSRFile->WD( (LPVOID)pObj, objSize );}bool KStateSer::Read( DWORD objSize, void *pObj ){  return ReadImpl( pObj, objSize );}bool KStateSer::ReadImpl( void *pObj, DWORD objSize ){  bool r = pSRFile->RD( pObj, objSize );  ASS( r );  return r;}bool KStateSer::ReadImpl( char *pBuf, size_t s ){  size_t l = 0;  if( !Read( l ) )    return false;  ASS( l<=s );  l = __min( l, s );  if( !ReadImpl( (void*)pBuf, l ) )    return false;  if( l > 0 )    pBuf[l-1] = 0;  return true;}bool KStateSer::Read( char *pszBuf, size_t size ){  return ReadImpl( pszBuf, size );}